export const DEFAULT_SYSTEM_MESSAGES_FLOATING_ID = 'application-shell-system-messages-floating';
export const DEFAULT_TOAST_MESSAGE_FLOATING_ID = 'application-shell-toast-messages';
/**
 * Makes a system message show up in the UI. Requires a neon-messages component to be in the page-chrome to show it.  MFEs should assume that the
     environment they are in will already have a neon-messages component present.
 * @param message Ex: [ 'Click on this text', {text: 'Google', href: 'http://www.google.com'} ]
 * @param controlConfig Ex: { sendTo: DEFAULT_SYSTEM_MESSAGES_FLOATING_ID, autoDismiss?: true, autoDismissTime: 8000, messageType: 'Info', title: 'Title Message', dismissable: true }
 * @returns A Promise that resolves to the id of the system message added.
 */
export function showSystemMessage(message, controlConfig) {
    let idCreatedCallback = null;
    return new Promise((resolve) => {
        idCreatedCallback = (id) => {
            resolve(id);
        };
        window.dispatchEvent(new CustomEvent('neonSystemMessageOpen', {
            detail: { message, controlConfig, idCreatedCallback },
        }));
    });
}
/**
 * Makes a system message show up in the UI.
 * @note Requires a neon-messages component to be in the page-chrome to show it.  MFEs should assume that the
        environment they are in will already have a neon-messages component present.
 * @note This function is dangerous as it might be tempting to build a DOM element on the fly and just set the innerHTML field.  If you do this it is
       your responsibility as a developer to ensure that the innerHTML string is guarded against cross site scripting attacks.
 * @param element Nested HTML content here
 * @param controlConfig  Ex: { sendTo: DEFAULT_SYSTEM_MESSAGES_FLOATING_ID, autoDismiss: true, autoDismissTime: 8000, messageType: 'Info', title: 'Title Message', dismissable: true }
 * @returns A Promise that resolves to the id of the system message added.
 */
export function showMessageDangerous(element, controlConfig) {
    return new Promise((resolve) => {
        window.dispatchEvent(new CustomEvent('neonSystemMessageOpen', {
            detail: {
                message: element,
                controlConfig,
                idCreatedCallback: (id) => {
                    resolve(id);
                }
            },
        }));
    });
}
/**
 * Makes a toast message show up in the UI.
 * @note Requires a neon-messages component to be in the page-chrome to show it. MFEs should assume that the
      environment they are in will already have a neon-messages component present.
 * @param message Ex: {
                heading: 'Heading',
                subheading: 'Subheading',
                date: Date(),
                type: 'info',
                buttons: [{
                    id: 'ok-button',
                    text: 'OK',
                    onUserClick: (): void,
                    type: 'primary',
                    showText: 'true',
                  }],
              },
 * @param controlConfig Ex: { sendTo: DEFAULT_TOAST_MESSAGE_FLOATING_ID, autoDismiss: true, autoDismissTime: 8000, messageType: 'Info' }
 * @returns A Promise that resolves to the id of the shown toast message.
 */
export function showToastMessage(message, controlConfig) {
    return new Promise((resolve) => {
        window.dispatchEvent(new CustomEvent('neonToastMessageOpen', {
            detail: {
                message,
                controlConfig,
                idCreatedCallback: (id) => {
                    resolve(id);
                }
            },
        }));
    });
}
/**
 * Makes a toast message go away from the UI.  MFEs should assume that the environment they are in
      will already have a neon-messages component present.
 * @param id Element id of the toast message
 */
export function closeToastById(id) {
    window.dispatchEvent(new CustomEvent('neonToastMessageCloseGlobal', {
        detail: { id }
    }));
}
/**
 * Makes a system message go away from the UI.  MFEs should assume that the environment they are in
      will already have a neon-messages component present.
 * @param id Element id of the system message
 */
export function closeSystemMessageById(id) {
    window.dispatchEvent(
    //Add comment
    new CustomEvent('neonSystemMessageCloseGlobal', {
        detail: { id }
    }));
}
